 useEffect(()=>{const q=firestoreQuery(collection(db,'posts'),orderBy('createdAt','desc'));return onSnapshot(q,snap=>setPosts(snap.docs.map(d=>({id:d.id,...d.data(),time:d.data().createdAt?.toDate?d.data().createdAt.toDate().toLocaleString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'только что',liked:!!d.data().likedBy?.includes(user.uid)}))),err=>notify('Не удалось загрузить ленту: '+err.message))},[user.uid]);
