 useEffect(()=>{const q=firestoreQuery(collection(db,'users',user.uid,'notifications'),orderBy('createdAt','desc'));return onSnapshot(q,s=>setNotifications(s.docs.map(d=>({id:d.id,...d.data()})).slice(0,30)))},[user.uid]);
 useEffect(()=>{const q=firestoreQuery(collection(db,'chats'),where('participants','array-contains',user.uid));return onSnapshot(q,s=>setChats(s.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(b.updatedAt?.toMillis?.()||0)-(a.updatedAt?.toMillis?.()||0))),e=>notify('Не удалось загрузить чаты: '+e.message))},[user.uid]);
 useEffect(()=>{if(!activeChat){setChatMessages([]);return}const q=firestoreQuery(collection(db,'chats',activeChat.id,'messages'),orderBy('createdAt','asc'));return onSnapshot(q,s=>setChatMessages(s.docs.map(d=>({id:d.id,...d.data()}))),e=>notify('Не удалось загрузить сообщения: '+e.message))},[activeChat?.id]);
 useEffect(()=>{if(!selectedPerson?.uid){setProfileFollowerCount(0);return}return onSnapshot(collection(db,'users',selectedPerson.uid,'followers'),s=>setProfileFollowerCount(s.size),()=>setProfileFollowerCount(0))},[selectedPerson?.uid]);
 useEffect(()=>{user.getIdTokenResult().then(t=>setIsAdmin(t.claims.admin===true)).catch(()=>setIsAdmin(false))},[user]);
