 useEffect(()=>{if(!isAdmin)return;const q=firestoreQuery(collection(db,'labRequests'),orderBy('createdAt','desc'));return onSnapshot(q,s=>setLabRequests(s.docs.map(d=>({id:d.id,...d.data()}))),e=>notify('Не удалось загрузить заявки: '+e.message))},[isAdmin]);
